struct recti { int values[4]; };
struct kellyslater_controller;

class PushMode {
protected:
    static const float TIME_PUSH_EFFECT;
    static const int MAX_TIE_SHARES;
    struct PLAYER {
        float share;
        int extraShare;
        recti viewport;
        kellyslater_controller *ks;
        int prevScore;
    };
    PLAYER players[2];
    float attackTimer;
    int scoreRequired;
    void CalcExtraShares(const int playerIdx);
    bool Attack(const int playerIdx);
    void CalcViewports(void);
public:
    void Update(const float dt);
};

__asm__(".equ CalcExtraShares__8PushModei, 0x00285CB0");
__asm__(".equ Attack__8PushModei, 0x00285D68");
__asm__(".equ CalcViewports__8PushMode, 0x00285EA0");

const float PushMode::TIME_PUSH_EFFECT = 0.5f;
const int PushMode::MAX_TIE_SHARES = 4;

void PushMode::Update(const float dt)
{
    int     i;
    bool    recalcViewports = false;

    for (i = 0; i < 2; i++)
        CalcExtraShares(i);

    while (players[0].extraShare > MAX_TIE_SHARES && players[1].extraShare > MAX_TIE_SHARES)
    {
        players[0].extraShare -= MAX_TIE_SHARES;
        players[1].extraShare -= MAX_TIE_SHARES;
    }

    attackTimer -= dt;
    if (attackTimer <= 0.0f)
    {
        attackTimer = TIME_PUSH_EFFECT;
        for (i = 0; i < 2; i++)
        {
            if (Attack(i))
                recalcViewports = true;
        }
    }

    if (recalcViewports)
        CalcViewports();
}
